HTTP.js is the frontend transport layer in packages/n3tx-core/src/n3tx_core/static/core/transport/HTTP.js. The stream() static method (lines ~353-399) does: POST with fetch, reads body as ReadableStream, parses SSE lines, dispatches to onChunk/onDone/onError callbacks.

Current flow (lines 370-388):
```javascript
function pump() {
    reader.read().then(({ done, value }) => {
        if (done) { onDone({}); return; }
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop();
        let eventType = 'chunk';
        for (const line of lines) {
            if (line.startsWith('event: ')) eventType = line.slice(7).trim();
            else if (line.startsWith('data: ')) {
                try {
                    const parsed = JSON.parse(line.slice(6));
                    if (eventType === 'error') onError(parsed);
                    else if (eventType === 'done') onDone(parsed);
                    else onChunk(parsed);
                } catch (e) { /* partial JSON, wait for more data */ }
            }
        }
        pump();
    }).catch(e => {
        if (e.name !== 'AbortError') onError(e);
    });
}
```

The fix: add a `_done` flag that prevents the second onDone call.

