            const stats = document.createElement('div');
            stats.className = 'msg-stats';
            stats.textContent = `${data.tool_calls} tool call${data.tool_calls > 1 ? 's' : ''}`;
            this.#currentMsgEl.appendChild(stats);
        }
        this.#scrollToBottom();
    }

