        this.#isStreaming = false;
        this.#els.send.disabled = false;
        this.#toolCards = null;
        this.#currentMsgEl?.querySelector('.cursor')?.remove();
        this.#currentMsgEl?.querySelector('.msg-thinking')?.remove();
